def is_multiply_prime(a):
    """Enhanced function that checks if the number is a product of 3 primes and also returns the planets between those primes' positions in the solar system.
    Example:
    is_multiply_prime(30) -> (True, ('Venus', 'Earth'))
    Because 30 = 2*3*5, and between 2nd (Venus), 3rd (Earth), and 5th (Jupiter) planets are Venus and Earth.
    """
    planet_names = ("Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune")

    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        for j in range(2, int(n**0.5) + 1):
            if n % j == 0:
                return False
        return True

    primes = [i for i in range(2, 100) if is_prime(i)]

    for i in primes:
        for j in primes:
            for k in primes:
                if i * j * k == a:
                    # Get planet indices (1-based to match planet order)
                    idx1, idx2, idx3 = i % 8, j % 8, k % 8
                    # Ensure indices are in order
                    start = min(idx1, idx2, idx3)
                    end = max(idx1, idx2, idx3)
                    # Get planets between them
                    if start < end:
                        planets_between = planet_names[start+1:end]
                    else:
                        planets_between = ()
                    return (True, tuple(planets_between))
    return (False, ())

