def starts_one_ends(n: int) -> dict:
    # Given a positive integer n, return a dictionary containing:
#     1. 'count': the count of n-digit numbers starting or ending with 1
#     2. 'second_smallest': the 2nd smallest unique digit in the count's digits (None if <2 unique digits)
#     3. 'is_power_of_ten': whether the count is a power of 10
#     :param n: int - A positive integer representing the number of digits
#     :return: dict - A dictionary with keys 'count', 'second_smallest', and 'is_power_of_ten'
#     Examples:
#     >>> starts_one_ends(2)
#     {'count': 18, 'second_smallest': 8, 'is_power_of_ten': False}
#     >>> starts_one_ends(1)
#     {'count': 1, 'second_smallest': None, 'is_power_of_ten': True}
#     >>> starts_one_ends(4)
#     {'count': 1800, 'second_smallest': 1, 'is_power_of_ten': False}
#     >>> starts_one_ends(3)
#     {'count': 180, 'second_smallest': 1, 'is_power_of_ten': False}
#     >>> starts_one_ends(5)
#     {'count': 18000, 'second_smallest': 1, 'is_power_of_ten': False}

        result = {}

        # 1. Calculate 'count': the count of n-digit numbers starting or ending with 1
        if n == 1:
            count = 1
        else:
            # For n > 1:
            # Numbers starting with 1: 1 * 10^(n-1)
            # Numbers ending with 1: 9 * 10^(n-2) (first digit cannot be 0)
            # Numbers starting AND ending with 1: 1 * 10^(n-2)
            # Using Inclusion-Exclusion: (Starts with 1) + (Ends with 1) - (Starts AND Ends with 1)
            # count = (10**(n-1)) + (9 * (10**(n-2))) - (1 * (10**(n-2)))
            # count = 10**(n-1) + 8 * (10**(n-2))
            # count = 10 * (10**(n-2)) + 8 * (10**(n-2))
            # count = 18 * (10**(n-2))
            count = 18 * (10**(n - 2))
        result['count'] = count

        # 2. Calculate 'second_smallest': the 2nd smallest unique digit in the count's digits
        str_count = str(count)
        unique_digits = sorted(list(set(int(d) for d in str_count)))
        if len(unique_digits) >= 2:
            result['second_smallest'] = unique_digits[1]
        else:
            result['second_smallest'] = None

        # 3. Calculate 'is_power_of_ten': whether the count is a power of 10
        # A number is a power of 10 if it can be written as 10^k for some non-negative integer k.
        # This means its string representation must be '1' followed by zero or more '0's.
        is_power_of_ten = (str_count[0] == '1' and all(c == '0' for c in str_count[1:]))
        result['is_power_of_ten'] = is_power_of_ten

        return result


