def numerical_letter_grade(grades):
    """Enhanced version that not only letter grades but also calculates grade statistics.
    Returns a dictionary containing:
    - 'grades': list of letter grades (same as original function)
    - 'distribution': histogram of grade distribution
    - 'top_grade': most common grade(s) with count
    - 'gpa_stats': dictionary with min, max, and average GPA

    Example:
    numerical_letter_grade([4.0, 3, 1.7, 2, 3.5]) == {
        'grades': ['A+', 'B', 'C', 'C+', 'A-'],
        'distribution': {'A+': 1, 'B': 1, 'C': 1, 'C+': 1, 'A-': 1},
        'top_grade': {'A+': 1, 'B': 1, 'C': 1, 'C+': 1, 'A-': 1},
        'gpa_stats': {'min': 1.7, 'max': 4.0, 'average': 2.84}
    }
    """

    # Original grading logic
    letter_grade = []
    for gpa in grades:
        if gpa == 4.0:
            letter_grade.append("A+")
        elif gpa > 3.7:
            letter_grade.append("A")
        elif gpa > 3.3:
            letter_grade.append("A-")
        elif gpa > 3.0:
            letter_grade.append("B+")
        elif gpa > 2.7:
            letter_grade.append("B")
        elif gpa > 2.3:
            letter_grade.append("B-")
        elif gpa > 2.0:
            letter_grade.append("C+")
        elif gpa > 1.7:
            letter_grade.append("C")
        elif gpa > 1.3:
            letter_grade.append("C-")
        elif gpa > 1.0:
            letter_grade.append("D+")
        elif gpa > 0.7:
            letter_grade.append("D")
        elif gpa > 0.0:
            letter_grade.append("D-")
        else:
            letter_grade.append("E")

    # Additional statistics
    # Grade distribution histogram
    distribution = {}
    for grade in letter_grade:
        distribution[grade] = distribution.get(grade, 0) + 1

    # Most common grade (from histogram code)
    top_grade = {}
    max_count = max(distribution.values()) if distribution else 0
    for grade, count in distribution.items():
        if count == max_count:
            top_grade[grade] = count

    # GPA statistics
    gpa_stats = {
        'min': min(grades) if grades else 0,
        'max': max(grades) if grades else 0,
        'average': sum(grades)/len(grades) if grades else 0
    }

    return {
        'grades': letter_grade,
        'distribution': distribution,
        'top_grade': top_grade,
        'gpa_stats': gpa_stats
    }

