def encrypt(s):
    """Create an enhanced encryption function that:
    1. Rotates the alphabet by 4 places (2*2) as before
    2. Only encrypts characters whose ASCII values are prime numbers
    3. For non-prime ASCII characters, applies a special transformation:
       - If the character is a digit, replaces it with its square modulo 10
       - Otherwise leaves it unchanged
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    d = 'abcdefghijklmnopqrstuvwxyz'
    out = ''

    for c in s:
        if c in d and is_prime(ord(c)):
            out += d[(d.index(c) + 4) % 26]
        elif c.isdigit():
            out += str((int(c)**2) % 10)
        else:
            out += c

    return out

