def enhanced_prime_digit_sum(lst):
    """Enhanced version that finds the largest prime, sums its digits, and also returns 
    the sorted list of primes by digit sum (ascending) as a secondary output.
    The main return is the sum of digits of the largest prime.
    The secondary return is a tuple of (sorted_primes, original_indices)."""

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all primes with their original indices
    primes_with_indices = [(num, idx) for idx, num in enumerate(lst) if is_prime(num)]

    if not primes_with_indices:
        return (0, ([], []))

    # Find largest prime
    max_prime = max(primes_with_indices, key=lambda x: x[0])[0]
    sum_digits = sum(int(d) for d in str(abs(max_prime)))

    # Sort primes by digit sum (using absolute value)
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    sorted_primes = sorted(primes_with_indices, key=lambda x: (digit_sum(x[0]), x[1]))
    primes_sorted = [num for num, idx in sorted_primes]
    original_indices = [idx for num, idx in sorted_primes]

    return (sum_digits, (primes_sorted, original_indices))

