def words_string(s):
    """
    Enhanced version that not only splits words but also:
    1. Counts numeric values in the string
    2. Calculates the sum of these numbers
    3. Returns a dictionary with both the word list and numeric information
    """
    if not s:
        return {'words': [], 'number_count': 0, 'number_sum': 0, 'contains_numbers': False}

    s_list = []
    numbers = []

    for letter in s:
        if letter == ',':
            s_list.append(' ')
        else:
            s_list.append(letter)

    s_joined = "".join(s_list)
    words = s_joined.split()

    for word in words:
        if word.isdigit():
            numbers.append(int(word))

    return {
        'words': words,
        'number_count': len(numbers),
        'number_sum': sum(numbers),
        'contains_numbers': bool(numbers)
    }

