def histogram(test):
    """Given a string representing space separated lowercase letters, return a dictionary
    where keys are letters and values are their FibFib sequence numbers based on occurrence counts.
    If a letter appears n times, its value is fibfib(n).
    Empty string returns empty dict.

    Example:
    histogram('a b c') == {'a': 0, 'b': 0, 'c': 0}  # fibfib(1) = 0
    histogram('a b b a') == {'a': 1, 'b': 1}         # fibfib(2) = 1
    histogram('b b b b a') == {'b': 4, 'a': 0}       # fibfib(4) = 2
    """

    def fibfib(n):
        if n == 0: return 0
        if n == 1: return 0
        if n == 2: return 1
        return fibfib(n-1) + fibfib(n-2) + fibfib(n-3)

    counts = {}
    for char in test.split():
        if char:
            counts[char] = counts.get(char, 0) + 1

    result = {}
    for char, count in counts.items():
        result[char] = fibfib(count)

    return result

