    >>> valid_date('04-12-2003')
    {'is_valid': True, 'time_period': 'past', 'is_leap_year': False}
    >>> valid_date('03-11-2000')
    {'is_valid': True, 'time_period': 'past', 'is_leap_year': False}
    """

