def largest_smallest_integers(lst: List[int]) -> Dict[str, Optional[object]]:
    """
    Enhanced function that returns a dictionary with:
    - 'largest_negative': largest negative integer (None if none exist)
    - 'smallest_positive': smallest positive integer (None if none exist)
    - 'odd_collatz_sequence': sorted odd numbers from Collatz sequence of absolute values
    - 'sum_absolute': sum of absolute values of all numbers
    :param lst: List[int] - A list of integers to process.
    :return: Dict[str, Optional[object]] - A dictionary containing the results as described above.
    Examples:
    >>> largest_smallest_integers([1, 3, 2, 4, 5, 6, -2])
    {'largest_negative': -2, 'smallest_positive': 1, 'odd_collatz_sequence': [1, 3, 5], 'sum_absolute': 23}
    >>> largest_smallest_integers([2, 4, 1, 3, 5, 7])
