    {'largest_negative': -1, 'smallest_positive': None, 'odd_collatz_sequence': [1, 3, 5], 'sum_absolute': 15}
    >>> largest_smallest_integers([-1, -3, -5, -6, 0])
    {'largest_negative': -1, 'smallest_positive': None, 'odd_collatz_sequence': [1, 3, 5], 'sum_absolute': 15}
