from typing import Dict
def valid_date(date: str) -> Dict[str, object]:
    """
    Validates a date string and provides additional information about it.
    The function checks:
    1. If the date is valid (correct format and logical day/month/year values)
    2. If the year is a leap year (for February dates)
    3. Whether the date is in the past, present, or future relative to current time
    :param date: str - A date string in MM-DD-YYYY format
    :return: Dict[str, object] - A dictionary with three keys:
        - 'is_valid': bool - whether the date is valid
        - 'time_period': str - one of 'past', 'present', or 'future'
        - 'is_leap_year': bool - whether the year is a leap year (only relevant for February dates)
    Examples:
    >>> valid_date('2003-04-12')
    {'is_valid': False, 'time_period': None, 'is_leap_year': False}
    >>> valid_date('15-01-2012')
    {'is_valid': False, 'time_period': None, 'is_leap_year': False}
    >>> valid_date('04-2003')
    {'is_valid': False, 'time_period': None, 'is_leap_year': False}
