def can_arrange(arr):
    """Enhanced function that:
    1. Finds the largest index where element < previous element (original functionality)
    2. Also checks if the array can form any triple (i<j<k) where arr[i]^2 + arr[j]^2 + arr[k]^2 is divisible by 3
    3. Returns a tuple containing both results
    """
    # Original functionality
    ind = -1
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            ind = i

    # New functionality inspired by get_max_triples
    triple_count = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (arr[i]**2 + arr[j]**2 + arr[k]**2) % 3 == 0:
                    triple_count += 1

    return (ind, triple_count)

