            if text[i] in "()":
                has_brackets = True
                if text[i] == "(":
                    bracket_stack.append(i)
                else:
                    if bracket_stack:
                        bracket_stack.pop()
                    else:
                        # Unmatched closing bracket
                        bracket_stack.append(-1)

            # Handle spaces
            if end - start > 2:
                new_text += "-" + text[i]
            elif end - start > 0:
                new_text += "_" * (end - start) + text[i]
            else:
                new_text += text[i]
            start, end = i + 1, i + 1
        i += 1

