def order_by_points(nums):
    """
    Enhanced function that sorts integers by digit sum (with negative handling) and
    also identifies the smallest even number with its index in the original list.
    Returns a tuple: (sorted_list, [smallest_even_value, its_index] or [])
    """
    def digits_sum(n: int) -> int:
        neg = 1
        if n < 0:
            n, neg = -1 * n, -1
        n = [int(i) for i in str(n)]
        n[0] = n[0] * neg
        return sum(n)

    # Original sorting functionality
    sorted_nums = sorted(nums, key=digits_sum)

    # Added functionality from pluck()
    if not nums:
        return (sorted_nums, [])

    evens = [x for x in nums if x % 2 == 0]
    if not evens:
        return (sorted_nums, [])

    min_even = min(evens)
    min_index = nums.index(min_even)

    return (sorted_nums, [min_even, min_index])

