def get_max_triples(n):
    """
    Enhanced version that:
    1. Generates the array as before
    2. Counts valid triples where sum is divisible by 3
    3. Additionally verifies if the sum is a product of 3 primes
    4. Returns a tuple of (total_valid_triples, prime_product_triples)
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    A = [i*i - i + 1 for i in range(1, n+1)]
    total_triples = 0
    prime_product_triples = 0

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                triple_sum = A[i] + A[j] + A[k]
                if triple_sum % 3 == 0:
                    total_triples += 1
                    # Check if sum is product of 3 primes
                    if triple_sum < 100:  # Optimization since primes are <100
                        for a in range(2, 101):
                            if not is_prime(a):
                                continue
                            for b in range(2, 101):
                                if not is_prime(b):
                                    continue
                                c = triple_sum // (a * b)
                                if a * b * c == triple_sum and is_prime(c):
                                    prime_product_triples += 1
                                    break
                            else:
